\section*{অধ্যায় 9}
\textbf{মানব জীবনের ধারাবাহিকতা} \\
\textbf{(CONTINUATION OF HUMAN LIFE)}

\begin{multicols}{2}
\textbf{প্রজনন প্রতিটি জীবের সহজাত প্রবর্তি। জীবনের ধারাবাহিকতা রক্ষায় এবং বংশবৃদ্ধির জন্য অন্যান্য সকল প্রাণীর মতো মানুষেরও প্রজনন সম্পন্ন হয়। মানুষের প্রজনন এবং যৌন ক্রিয়া সমাজ জীবনের সাথে ওত্থোতভাবে জড়িত। নারী ও পুরুষের যৌন মিলনের দ্বারা মানুষের প্রজনন সম্পন্ন হয়। এ ঘটনার সাথে জড়িত আছে বিভিন্নরকম শারীরবৃত্তীয় প্রক্রিয়া যাদের যে কোনো একটিতে সমস্যা হলে প্রজনন প্রক্রিয়া ব্যতিরেক হয়। সমাজের সকল ধরনের মানুষ প্রজননের সাথে জড়িত বলে এ পদ্ধতি সম্পর্কে সাধারণ জ্ঞান থাকা বাধ্যনী। এ অধ্যায়ে মানুষ প্রজননতন্ত্র এবং প্রজননের বিভিন্ন দিক নিয়ে আলোচনা করা হয়েছে।

\textbf{প্রধান শব্দাবলি (Key words)}
\begin{itemize}
    \item প্রজননতন্ত্র
    \item বয়োঃসন্ধিকাল
    \item স্পার্মাটোজোনেসিস
    \item উওজেনেসিস
    \item নিষেক
    \item ইম্প্লান্টেশন
    \item অমরা
    \item নাভী রজ্জু
    \item টেস্ট টিউব বেবি
    \item ভেনারিয়েল ডিজিস
    \item এইডস
\end{itemize}

\textbf{পরিষেব সংখ্যা 11। এ অধ্যায় পাঠ শেষে শিক্ষার্থীরা যা পারবে -}

\begin{tabular}{|p{10cm}|p{10cm}|}
\hline
\textbf{শিক্ষানির্দেশ} & \textbf{বিষয়বস্তু} \\
\hline
1. পুরুষ ও স্ত্রী প্রজননতন্ত্র ও এর হরমোনাল ক্রিয়া ব্যাখ্যা করতে পারবে। & \begin{itemize}
    \item পুরুষ প্রজননতন্ত্র ও এর হরমোনাল ক্রিয়া
    \item স্ত্রী প্রজননতন্ত্র ও এর হরমোনাল ক্রিয়া
\end{itemize} \\
2. প্রজননের বিভিন্ন পর্যায় ও দশা বর্ণনা করতে পারবে। & \begin{itemize}
    \item প্রজননের বিভিন্ন পর্যায় ও দশা
\end{itemize} \\
3. গর্ভবাস্ত্ব করণীয় দিকসমূহ চিহ্নিত করতে পারবে। & \begin{itemize}
    \item রজঞ্চক্র ও বয়োঃসন্ধিকাল ও এ সময়ের পরিবর্তনসমূহ
\end{itemize} \\
\hline
